const n = pieces, i = @ptnum + 0.5;
const jit = 0.3 / sqrt(n);
let x = frac(rand(seed, 11) + i * 0.7548776662466927) + (rand(@ptnum, seed, 1) - 0.5) * jit;
let y = frac(rand(seed, 12) + i * 0.5698402909980532) + (rand(@ptnum, seed, 2) - 0.5) * jit;
x = clamp(x, 0.01, 0.99); y = clamp(y, 0.01, 0.99);
let p = [(x - 0.5) * wall_width, y * wall_height, (rand(@ptnum, seed, 3) - 0.5) * thickness * 0.3];
const hit = [0, wall_height * 0.45], R = 0.35 * min(wall_width, 2 * wall_height);
const dx = p.x - hit[0], dy = p.y - hit[1], r = sqrt(dx * dx + dy * dy);
if (r < R && r > 0) { const k = pow(r / R, 0.6 * impact); p = [hit[0] + dx * k, hit[1] + dy * k, p.z]; }
@P = p;

const seen = new Set();
for (let i = 0; i < nprims(0); i++) seen.add(prim(0, 'part', i));
i@piece_count = seen.size;

const id = @class, site = point(1, 'P', id);
const hit = [0, wall_height * 0.45, -thickness / 2];
const d = sub(site, hit);
const reach = 0.2 * min(wall_width, 2 * wall_height);
const f = impact * exp(-(d.x * d.x + d.y * d.y) / (reach * reach));
const dir = normalize([d.x * 0.5, d.y * 0.3 + 0.25, 1]);
const k = sqrt(max(sqrt(wall_width * wall_height / pieces), thickness) / 0.56);
const side = rand(id, seed, 6) < 0.5 ? -1 : 1;
v@v = add(mul(dir, 9 * f * (0.8 + 0.4 * rand(id, seed, 7))), [(rand(id, seed, 8) - 0.5) * 0.4 * k, 0, side * 1.6 * k * (0.5 + rand(id, seed, 9))]);
v@w = add([side * 4 / k * (0.7 + 0.6 * rand(id, seed, 10)), 0, 0], mul(randdir(id * 13 + seed), 1 + 6 * f));

const seen = new Set();
for (let i = 0; i < nprims(0); i++) seen.add(prim(0, 'part', i));
i@piece_count = seen.size;
